-- Large CSV exports are generated by a job into private storage and downloadable only by the requester,
-- whose class access is rechecked at download.
create table report_exports (
    id           uuid        primary key,
    class_id     uuid        not null references classes (id),
    requested_by uuid        not null references users (id),
    type         varchar(16) not null check (type in ('PROGRESS', 'SCORES')),
    status       varchar(16) not null check (status in ('PENDING', 'READY', 'FAILED')),
    storage_key  varchar(200) not null unique,
    created_at   timestamptz not null,
    completed_at timestamptz
);

create index report_exports_requester_idx on report_exports (requested_by, created_at desc);
create index lesson_progress_activity_idx on lesson_progress (enrollment_id, last_activity_at);
